Method.Implementation:
	 Set tSC= $$$OK
	 $$$TRACE(" Inside InvokePostService ")

	  try {

	 set jsonBodyData = pInput.Read(.len,.status)
	 //DECODE bASE64
	 set data = $SYSTEM.Encryption.Base64Decode(jsonBodyData)
	 	// set dynObj = jsonBodyData

	 $$$TRACE(" Immunization from Cerner Service) : "_jsonBodyData)	 
	 set jsonStrContainer=##class(Ens.StringContainer).%New()
  //  set jsonStrContainer.StringValue= jsonBodyData
    set jsonStrContainer.StringValue= data

    //create Hl7 message 
     set pHL7=##class(EnsLib.HL7.Message).ImportFromString(jsonStrContainer.StringValue,.sc) $$$ThrowOnError(sc)
	//  set tDocType=##class(EnsLib.HL7.Schema).ResolveSchemaTypeToDocType("ImmunizationLoadCerner:VXU_V04", pHL7.Name, sc)	$$$ThrowOnError(sc)
	//   set tDocType=##class(EnsLib.HL7.Schema).ResolveSchemaTypeToDocType("2.4:VXU_V04", pHL7.Name, sc)	$$$ThrowOnError(sc)
	    set tDocType=##class(EnsLib.HL7.Schema).ResolveSchemaTypeToDocType("2.4", "VXU_V04", sc)	$$$ThrowOnError(sc)
	   // Set DocType and build map
        set pHL7.DocType=tDocType $$$ThrowOnError(sc)
        set sc=pHL7.BuildMap()   
	 set pResponse = pHL7

    // set pResponse = jsonStrContainer
    // set pResponse = dynObj.%ToJSON()
     $$$TRACE(..TargetConfigNames)


     For iTarget=1:1:$L(..TargetConfigNames, ",")        { 
          Set tOneTarget=$ZStrip($P(..TargetConfigNames,",",iTarget),"<>W")  
          $$$TRACE("tOneTarget " _ tOneTarget)
          do ..SendRequestAsync(tOneTarget,pResponse)
      }




 }catch e
	{
		 $$$TRACE("  Exception: " _ e)
		 set errTxt = $System.Status.GetErrorText(e)		 
		 Set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError(..%ConfigName,errTxt)	  
		 set tSC = $$$OK

	}
		  quit tSC

Do ##super(.pArray,pItem)
If pItem.GetModifiedSetting("TargetConfigNames",.tValue) {
	For i=1:1:$L(tValue,",") { Set tOne=$ZStrip($P(tValue,",",i),"<>W")  Continue:""=tOne  Set pArray(tOne)="" }
}
